package vn.edu.fpt.seal.modules.feedback.mapper; import vn.edu.fpt.seal.modules.feedback.dto.MentorFeedbackResponse; import vn.edu.fpt.seal.modules.feedback.entity.MentorFeedback;
public final class MentorFeedbackMapper{private MentorFeedbackMapper(){} public static MentorFeedbackResponse toResponse(MentorFeedback f){var tm=f.getTrackMentor(); return MentorFeedbackResponse.builder().id(f.getId()).trackMentorId(tm.getId()).mentorId(tm.getUser().getId()).mentorEmail(tm.getUser().getEmail()).trackId(tm.getTrack().getId()).trackName(tm.getTrack().getName()).teamId(f.getTeam().getId()).teamName(f.getTeam().getName()).roundId(f.getRound()==null?null:f.getRound().getId()).roundName(f.getRound()==null?null:f.getRound().getName()).content(f.getContent()).createdAt(f.getCreatedAt()).updatedAt(f.getUpdatedAt()).build();}}
